function compileEnzyme(name, def) {
  let top = null, bot = null, site = '';
  for (const c of def) {
    if (c === '^') top = site.length;
    else if (c === '_') bot = site.length;
    else site += c;
  }
  if (!/^[ACGTRYKMSWBDHVN]+$/.test(site)) return null;
  if (top === null) top = site.length; // e.g. "CCTC" w/o cut info → treat as cutting after site
  if (bot === null) bot = site.length - top;
  const rc = revcomp(site);
  const lead = site.match(/^N*/)[0].length, trail = site.match(/N*$/)[0].length;
  return { name, lead, trail, rcLead: rc.match(/^N*/)[0].length, rcTrail: rc.match(/N*$/)[0].length, def, site, top, bot, len: site.length, palin: rc === site, rcRegex: new RegExp('(?=(' + iupacRegexSrc(rc) + '))', 'g'), regex: new RegExp('(?=(' + iupacRegexSrc(site) + '))', 'g') };
}

/* Type IIS enzymes commonly used for Golden Gate / MoClo / GoldenBraid assembly */
const GOLDEN_GATE = new Set(['BsaI', 'BsmBI', 'Esp3I', 'BbsI', 'BpiI', 'SapI', 'BspQI', 'AarI', 'PaqCI', 'BtgZI', 'EarI', 'BsmAI', 'BspMI']);
let ENZYMES = [];
let enzVersion = 0;
function buildEnzymes() {
  const list = [];
  for (const line of ENZYME_DEFS.split('\n')) {
    const [n, d] = line.trim().split(/\s+/); if (!n || !d || d === 'skip') continue;
    const e = compileEnzyme(n, d); if (e) list.push(e);
  }
  const have = new Set(list.map(e => e.name));
  if (typeof nebExtraDefs === 'function') for (const [n, d] of nebExtraDefs()) { if (have.has(n)) continue; const e = compileEnzyme(n, d); if (e) { e.neb = true; list.push(e); have.add(n); } }
  for (const u of store.get('userEnzymes', [])) { if (have.has(u.name)) continue; const e = compileEnzyme(u.name, u.def); if (e) { e.user = true; list.push(e); } }
  list.sort((a, b) => a.name.localeCompare(b.name, 'en', { sensitivity: 'base' }));
  ENZYMES = list; enzVersion++;
}
